import {W,H,createWorld,tick,stats,declareWar,peace,rebel,log,validate} from './engine.js';
const $=s=>document.querySelector(s),canvas=$('#map'),ctx=canvas.getContext('2d');let world=createWorld(),selected=null,running=true,speed=1,layer='political',zoom=1,pan={x:0,y:0},cw=0,ch=0,drag=null,toastTimer;const terrainCanvas=document.createElement('canvas');terrainCanvas.width=W;terrainCanvas.height=H;const terrainCtx=terrainCanvas.getContext('2d');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const compact=n=>Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n);function toast(text){$('#toast').textContent=text;$('#toast').style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.opacity=0,3000);}
function view(){const scale=Math.min(cw/W,ch/H)*.93*zoom;return {scale,x:(cw-W*scale)/2+pan.x,y:(ch-H*scale)/2+pan.y};}
function draw(){const dpr=devicePixelRatio||1;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#193740';ctx.fillRect(0,0,cw,ch);ctx.strokeStyle='#adc2b00b';ctx.lineWidth=1;for(let x=0;x<cw;x+=45){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,ch);ctx.stroke();}for(let y=0;y<ch;y+=45){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(cw,y);ctx.stroke();}const v=view();ctx.save();ctx.translate(v.x,v.y);ctx.scale(v.scale,v.scale);const pixels=terrainCtx.createImageData(W,H);world.owner.forEach((n,i)=>{if(n<0)return;const t=world.terrain[i];let color=layer==='political'?world.nations[n].color:t>.33?'#c8c1a2':t>.2?'#87977b':t>.09?'#6c8c74':'#a1ad85';const rgb=color.match(/[a-f\d]{2}/gi).map(x=>parseInt(x,16));const shade=(layer==='political'?.94:1)+(Math.sin(i*127.1)*.035)-(t>.35?.13:0);for(let k=0;k<3;k++)pixels.data[i*4+k]=rgb[k]*shade*(selected!==null&&selected!==n&&layer==='political'?.78:1);pixels.data[i*4+3]=255;});terrainCtx.putImageData(pixels,0,0);ctx.imageSmoothingEnabled=false;ctx.shadowColor='#081e29';ctx.shadowBlur=9;ctx.drawImage(terrainCanvas,0,0);ctx.shadowBlur=0;ctx.lineWidth=.22;world.owner.forEach((n,i)=>{if(n<0)return;const x=i%W,y=Math.floor(i/W);ctx.strokeStyle='#17333895';ctx.beginPath();if(x===0||world.owner[i-1]!==n){ctx.moveTo(x,y);ctx.lineTo(x,y+1);}if(y===0||world.owner[i-W]!==n){ctx.moveTo(x,y);ctx.lineTo(x+1,y);}if(x===W-1||world.owner[i+1]<0){ctx.moveTo(x+1,y);ctx.lineTo(x+1,y+1);}if(y===H-1||world.owner[i+W]<0){ctx.moveTo(x,y+1);ctx.lineTo(x+1,y+1);}ctx.stroke();if(world.terrain[i]>.3&&i%11===0){ctx.strokeStyle='#354f4855';ctx.lineWidth=.18;ctx.beginPath();ctx.moveTo(x-.4,y+.6);ctx.lineTo(x+.3,y-.6);ctx.lineTo(x+1,y+.6);ctx.stroke();ctx.lineWidth=.22;}});const counts=stats(world);world.nations.forEach((n,id)=>{if(!counts[id])return;const x=n.capital%W+.5,y=Math.floor(n.capital/W)+.5;ctx.fillStyle='#f2e5b8';ctx.strokeStyle='#203b3d';ctx.lineWidth=.25;ctx.beginPath();ctx.arc(x,y,.65,0,Math.PI*2);ctx.fill();ctx.stroke();if(counts[id]>80){ctx.font=`${selected===id?'600':'500'} ${Math.max(1.7,Math.min(2.6,Math.sqrt(counts[id])*.08))}px Georgia`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#172f31';ctx.strokeStyle='#ddd6b77a';ctx.lineWidth=.4;const text=n.name.toUpperCase();const lx=Math.max(17,Math.min(W-17,x)),ly=y+3;ctx.strokeText(text,lx,ly);ctx.fillText(text,lx,ly);}});ctx.restore();}
function resize(){const r=canvas.getBoundingClientRect();cw=r.width;ch=r.height;canvas.width=cw*(devicePixelRatio||1);canvas.height=ch*(devicePixelRatio||1);draw();}new ResizeObserver(resize).observe(canvas);
function update(){const counts=stats(world),total=counts.reduce((a,b)=>a+b,0);$('#year').textContent=world.year;$('#seed-label').textContent=`SEED / ${world.seed}`;$('#nation-count').textContent=counts.filter(Boolean).length;$('#population').textContent=compact(world.nations.reduce((a,n)=>a+n.population,0));$('#war-count').textContent=world.wars.length;$('#nations').innerHTML=world.nations.filter(n=>counts[n.id]).sort((a,b)=>counts[b.id]-counts[a.id]).map(n=>`<button class="nation ${selected===n.id?'active':''}" data-nation="${n.id}"><div class="nation-line"><i class="dot" style="background:${n.color}"></i>${esc(n.name)}<span>${Math.round(counts[n.id]/total*100)}%</span></div><div class="bar"><div style="width:${counts[n.id]/total*100}%;background:${n.color}"></div></div></button>`).join('');$('#events').innerHTML=world.events.slice(0,30).map(e=>`<article class="event ${e.type==='war'?'war':e.type==='peace'?'peace':''}"><small>YEAR ${e.year}</small><p>${esc(e.text)}</p></article>`).join('');$('#event-count').textContent=`${world.events.length} EVENTS`;inspect(counts);draw();}
function inspect(counts){if(selected===null)return;const n=world.nations[selected],alive=counts[selected]>0;const enemies=world.wars.filter(p=>p[0]===selected||p[1]===selected).map(p=>world.nations[p[0]===selected?p[1]:p[0]].name);const allies=world.alliances.filter(p=>p.includes(selected)).map(p=>world.nations[p[0]===selected?p[1]:p[0]].name);const previous=$('#rival')?.value;$('#inspector').innerHTML=`<i class="dot" style="background:${n.color};width:22px;height:25px"></i><h2 class="dossier-title">${esc(n.name)}</h2><div class="nation-subtitle">${!alive?'A FALLEN KINGDOM':enemies.length?'AT WAR · '+enemies.length+' FRONTS':'AT PEACE · SOVEREIGN NATION'}</div><div class="metrics"><div><span>Population</span><b>${compact(n.population)}</b></div><div><span>Territory</span><b>${counts[selected]} <small>tiles</small></b></div><div><span>Treasury</span><b>${Math.floor(n.wealth)} gold</b></div><div><span>Stability</span><b>${Math.round(n.stability)}%</b></div></div><div class="relations">Allies: ${esc(allies.join(', ')||'None')}<br>Enemies: ${esc(enemies.join(', ')||'None')}</div><div class="section-title">SHAPE THEIR DESTINY</div><div class="actions"><button data-action="bless" ${!alive?'disabled':''}>✧ Bless nation</button><button data-action="peace" ${!enemies.length?'disabled':''}>⚑ Make peace</button><button data-action="rebel" ${counts[selected]<80?'disabled':''}>⚡ Stir rebellion</button><button data-action="follow" ${!alive?'disabled':''}>◎ Find capital</button></div><select id="rival" class="war-select" aria-label="Choose rival nation">${world.nations.filter(m=>m.id!==selected&&counts[m.id]).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select><button class="wide" data-action="war" ${!alive?'disabled':''}>⚔ Declare war on selected rival</button>`;if(previous&&[...$('#rival').options].some(o=>o.value===previous))$('#rival').value=previous;}
$('#nations').addEventListener('click',e=>{const el=e.target.closest('[data-nation]');if(el){selected=Number(el.dataset.nation);update();}});$('#inspector').addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action||selected===null)return;const n=world.nations[selected];if(action==='bless'){n.wealth=Math.min(999,n.wealth+100);n.stability=Math.min(100,n.stability+15);log(world,`A golden age dawns for ${n.name}.`,'peace');}if(action==='peace')peace(world,selected);if(action==='rebel'&&!rebel(world,selected))toast('This kingdom cannot split further.');if(action==='war'&&!declareWar(world,selected,Number($('#rival').value)))toast('These nations are already at war.');if(action==='follow'){zoom=2;const scale=Math.min(cw/W,ch/H)*.93*zoom;pan={x:(W/2-n.capital%W)*scale,y:(H/2-Math.floor(n.capital/W))*scale};}update();});
function cell(e){const r=canvas.getBoundingClientRect(),v=view(),x=Math.floor((e.clientX-r.left-v.x)/v.scale),y=Math.floor((e.clientY-r.top-v.y)/v.scale);return x>=0&&x<W&&y>=0&&y<H?y*W+x:-1;}
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y,moved:false};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;pan={x:drag.px+dx,y:drag.py+dy};draw();$('#tooltip').style.display='none';return;}const i=cell(e),n=i>=0?world.owner[i]:-1;const tip=$('#tooltip');tip.style.display=n>=0?'block':'none';if(n>=0){tip.textContent=world.nations[n].name;const r=canvas.getBoundingClientRect();tip.style.left=Math.min(cw-160,e.clientX-r.left+12)+'px';tip.style.top=Math.max(0,e.clientY-r.top-35)+'px';}});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved){const i=cell(e);if(i>=0&&world.owner[i]>=0){selected=world.owner[i];update();}}drag=null;});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('pointerleave',()=>$('#tooltip').style.display='none');canvas.addEventListener('wheel',e=>{e.preventDefault();const old=zoom;zoom=Math.max(.7,Math.min(5,zoom*Math.exp(-e.deltaY*.001)));pan.x*=zoom/old;pan.y*=zoom/old;draw();},{passive:false});$('#reset-view').onclick=()=>{zoom=1;pan={x:0,y:0};draw();};document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;document.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));draw();});
function setRunning(value){running=value;$('#play').textContent=running?'Ⅱ Pause':'▶ Play';$('.timeline-note').textContent=running?'History is unfolding':'Time stands still';}$('#play').onclick=()=>setRunning(!running);$('#step').onclick=()=>{setRunning(false);tick(world);update();};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);document.querySelectorAll('[data-speed]').forEach(x=>x.classList.toggle('active',x===b));});setInterval(()=>{if(running&&!$('#new-dialog').open){for(let i=0;i<speed;i++)tick(world);update();}},900);
$('#new').onclick=()=>{$('#seed').value='WORLD-'+Math.floor(Math.random()*99999);$('#new-dialog').showModal();};$('#cancel').onclick=()=>$('#new-dialog').close();$('#world-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);world=createWorld(String(data.get('seed')),Number(data.get('count')));selected=null;zoom=1;pan={x:0,y:0};$('#inspector').innerHTML='<div class="empty-inspector"><h2>A new age begins.</h2><p>Select a kingdom to discover its story.</p></div>';$('#new-dialog').close();setRunning(true);update();};$('#save').onclick=()=>{try{localStorage.setItem('world-simulation-save',JSON.stringify(world));toast('World saved in this browser.');}catch{toast('Browser storage unavailable. Use Export instead.');}};function restore(s){world=validate(s);selected=null;pan={x:0,y:0};zoom=1;$('#inspector').innerHTML='<div class="empty-inspector"><h2>History returns.</h2><p>Select a kingdom to continue its story.</p></div>';setRunning(false);update();}$('#load').onclick=()=>{try{const saved=localStorage.getItem('world-simulation-save');if(!saved)return toast('No saved world yet.');restore(JSON.parse(saved));toast('Saved world restored. Press Play to continue.');}catch{toast('Could not load this save.');}};$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(world,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`world-year-${world.year}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('World and chronicle exported.');};$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error();restore(JSON.parse(await f.text()));toast('World imported.');}catch{toast('Invalid world file. Choose an exported JSON save.');}e.target.value='';};document.addEventListener('keydown',e=>{if(e.code==='Space'&&!/INPUT|SELECT|BUTTON|TEXTAREA/.test(e.target.tagName)&&!$('#new-dialog').open){e.preventDefault();setRunning(!running);}});update();
